    unsigned b276 = stwo_m31_add(b273, b275);
    e2 = StwoCudaQm31{ b276, b264, b264, b264 };
    e1 = stwo_qm31_mul(e3, e2);
    e2 = stwo_qm31_add(e0, e1);
